import{_ as o,a0 as p,w as u,s as r,ao as x,I as i,x as n,a1 as l,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在Arch上使用Syslinux替代GRUB | LCTT x X-CMD","titleTemplate":false,"description":"在Arch上使用Syslinux替代GRUB | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Arch上使用Syslinux替代GRUB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Arch上使用Syslinux替代GRUB | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/How to Replace GRUB with Syslinux on Arch Linux","title":"在Arch上使用Syslinux替代GRUB","tag":"201402","desc":""},"relativePath":"201402/How to Replace GRUB with Syslinux on Arch Linux.md","filePath":"[post].md"}'),a={name:"201402/How to Replace GRUB with Syslinux on Arch Linux.md"};function y(d,t,S,f,m,R){const s=p("Link");return u(),r("div",null,[t[14]||(t[14]=x(`<h1 id="在arch上使用syslinux替代grub" tabindex="-1">在Arch上使用Syslinux替代GRUB <a class="header-anchor" href="#在arch上使用syslinux替代grub" aria-label="Permalink to “在Arch上使用Syslinux替代GRUB”">​</a></h1><p>這個教程用於教授Arch Linux用户如何在Arch下安裝Syslinux——一個輕量級、快速並且現代感十足的系統引導程序，用來替換掉系統自帶的GRUB引導程序。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Replace-GRUB-with-Syslinux-on-Arch-Linux-415394-2.jpg" alt=""></p><p>實際上，Syslinux不是一個簡單的開機啓動裝載程序，它支持多種啓動引導方式，本地載入，通過PXE網絡載入，以及通過可移動媒體載入。並且，它還同時支持MBR和GPT磁盤，以及RAID設置。</p><p>在開始你實際操作之前，你應該知道Syslinux支持如下文件系統：FAT，EXT2，EXT3，EXT4和Btrfs，而且Syslinux能夠運行在支持UEFI或BIOS的機器上。到目前為止，Syslinux還不能訪問自己所在的分區之外的文件。</p><p>在你替換GRUB啓動之前，請認真考慮，這只是一個可選的嘗試，這個嘗試有可能會給你帶來一些麻煩。如果説你只是想感受一下新鮮的事物，或是已經厭倦了GRUB的界面，沒問題來嘗試嘗試Syslinux吧。</p><p>###在Arch box 中安裝Syslinux ###</p><p>該説的都説完了，下面我們來開始安裝Syslinux，準備替換掉已有的GRUB或者GRUB2啓動程序。打開一個終端，輸入如下命令來安裝Syslinux</p><pre><code>sudo pacman -S syslinux
</code></pre><p>安裝完成後，你應該注意到一條消息，將指導您如何分別在BIOS或UEFI機器上部署Syslinux引導裝載程序。BIOS用户比較幸運，因為他們只需要運行syslinux-install_update 腳本就行了，這個腳本是Matthew Gyurgyik編寫的，用來在BIOS機器上成功的部署Syslinux。</p><p>###在Arch box上部署Syslinux###</p><p>如果你擁有的是一個單獨的/boot分區，你要保證你是在/boot分區上執行的這個腳本。在終端中輸入如下命令：</p><pre><code>sudo syslinux-install_update -i -a -m
</code></pre><p>這個腳本會安裝必需的文件，並且用啓動標記標記分區，同時會安裝MBR引導代碼。</p><p>###配置Syslinux###</p><p>這是非常非常重要的一步，任何人都不能忽略它，因為如果你的Syslinux沒有正確的配置，你的電腦將不能啓動。請再次注意。</p>`,16)),i("p",null,[t[1]||(t[1]=n("目前，Syslinux能通過/boot/syslinux/syslinux.cfg文件進行配置。在",-1)),l(s,{href:"https://wiki.archlinux.org/index.php/syslinux#Configuration"},{default:e(()=>[...t[0]||(t[0]=[n("the official Arch Linux page of Syslinux",-1)])]),_:1}),t[2]||(t[2]=n(" 中查看詳細的配置指令。當你配置成功後，重啓你的系統然後來看看新的啓動引導程序效果如何！",-1))]),t[15]||(t[15]=i("p",null,"如果你有任何的問題，請毫不猶豫的在評論中提出！",-1)),t[16]||(t[16]=i("hr",null,null,-1)),i("p",null,[t[4]||(t[4]=n("via: ",-1)),l(s,{href:"http://news.softpedia.com/news/How-to-Replace-GRUB-with-Syslinux-on-Arch-Linux-415394.shtml"},{default:e(()=>[...t[3]||(t[3]=[n("http://news.softpedia.com/news/How-to-Replace-GRUB-with-Syslinux-on-Arch-Linux-415394.shtml",-1)])]),_:1})]),i("p",null,[t[7]||(t[7]=n("譯者：",-1)),l(s,{href:"https://github.com/dy2009"},{default:e(()=>[...t[5]||(t[5]=[n("dy2009",-1)])]),_:1}),t[8]||(t[8]=n(" 校對：",-1)),l(s,{href:"http://blog.csdn.net/tinyeyeser"},{default:e(()=>[...t[6]||(t[6]=[n("Mr小眼兒",-1)])]),_:1})]),i("p",null,[t[11]||(t[11]=n("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原創翻譯，",-1)),l(s,{href:"http://linux.cn/"},{default:e(()=>[...t[10]||(t[10]=[n("Linux中國",-1)])]),_:1}),t[13]||(t[13]=n(" 榮譽推出",-1))])])}const A=o(a,[["render",y]]);export{T as __pageData,A as default};
